{
  "info": {
    "title": "UAE Account Information API",
    "description": "## UAE Open Finance Account Information API Specification",
    "version": "v2.1-errata2"
  },
  "servers": [
    {
      "url": "/open-finance/account-information/v2.1"
    }
  ],
  "source_path": "/accounts/{AccountId}/scheduled-payments",
  "operations": {
    "get": {
      "tags": [
        "Scheduled Payments"
      ],
      "summary": "Get Scheduled Payments",
      "description": "The following permissions are applicable to this resource:\n\n* ReadScheduledPaymentsBasic\n\n* ReadScheduledPaymentsDetail\n\nRefer to the Permissions and Data Clusters section of the Customer Data page for further information.\n",
      "operationId": "GetScheduledPayments",
      "parameters": [
        {
          "$ref": "#/components/parameters/Authorization"
        },
        {
          "$ref": "#/components/parameters/AccountId"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        }
      ],
      "responses": {
        "200": {
          "$ref": "#/components/responses/200AccountsAccountIdScheduledPaymentsRead"
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "404": {
          "$ref": "#/components/responses/404Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "security": [
        {
          "UserOAuth2Security": [
            "openid",
            "accounts"
          ]
        }
      ]
    }
  }
}

{
  "name": "authorization",
  "in": "header",
  "required": true,
  "description": "An authorization Token as per https://tools.ietf.org/html/rfc6750",
  "schema": {
    "type": "string"
  }
}

{
  "name": "AccountId",
  "in": "path",
  "description": "AccountId",
  "required": true,
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-auth-date",
  "required": false,
  "description": "The time when the User last logged in with the TPP. \nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below: \nSun, 10 Sep 2017 19:43:31 UTC",
  "schema": {
    "type": "string",
    "pattern": "^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\d{4} \\d{2}:\\d{2}:\\d{2} (GMT|UTC)$"
  }
}

{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": false,
  "description": "The User's IP address if the User is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-interaction-id",
  "required": false,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-customer-user-agent",
  "description": "Indicates the user-agent that the User is using.",
  "required": false,
  "schema": {
    "type": "string"
  }
}

{
  "description": "Scheduled Payments Read",
  "headers": {
    "x-fapi-interaction-id": {
      "description": "An RFC4122 UID used as a correlation id.",
      "required": true,
      "schema": {
        "type": "string"
      }
    }
  },
  "content": {
    "application/json; charset=utf-8": {
      "schema": {
        "$ref": "#/components/schemas/AEReadScheduledPayment"
      }
    },
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/AEReadScheduledPayment"
      }
    },
    "application/jwt": {
      "schema": {
        "$ref": "#/components/schemas/AEReadScheduledPaymentSigned"
      }
    }
  }
}

{
  "description": "List of Scheduled Payments for an Account",
  "type": "object",
  "required": [
    "Data",
    "Links",
    "Meta"
  ],
  "properties": {
    "Data": {
      "type": "object",
      "description": "Primary data for the resource",
      "required": [
        "AccountId",
        "ScheduledPayment"
      ],
      "properties": {
        "AccountId": {
          "$ref": "#/components/schemas/AccountId"
        },
        "ScheduledPayment": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEScheduledPayment"
          }
        }
      },
      "additionalProperties": false
    },
    "Links": {
      "$ref": "#/components/schemas/Links"
    },
    "Meta": {
      "$ref": "#/components/schemas/MetaTotalPages"
    }
  },
  "additionalProperties": false
}

{
  "description": "A unique and immutable identifier produced by the LFI to identify the account resource.This identifier has no meaning to the account owner (User 1).",
  "type": "string",
  "minLength": 1,
  "maxLength": 40
}

{
  "description": "Scheduled Payments for a specific AccountId",
  "type": "object",
  "required": [
    "ScheduledPaymentId",
    "ScheduledPaymentDateTime",
    "ScheduledType",
    "InstructedAmount"
  ],
  "properties": {
    "ScheduledPaymentId": {
      "$ref": "#/components/schemas/ScheduledPaymentId"
    },
    "AccountHolderName": {
      "$ref": "#/components/schemas/AccountHolderName"
    },
    "AccountHolderShortName": {
      "$ref": "#/components/schemas/AccountHolderShortName"
    },
    "ScheduledType": {
      "$ref": "#/components/schemas/AEExternalScheduleTypeCode"
    },
    "ScheduledPaymentDateTime": {
      "$ref": "#/components/schemas/ScheduledPaymentDateTime"
    },
    "CreditorReference": {
      "$ref": "#/components/schemas/Reference"
    },
    "DebtorReference": {
      "$ref": "#/components/schemas/DebtorReference"
    },
    "InstructedAmount": {
      "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_1"
    },
    "CreditorAgent": {
      "$ref": "#/components/schemas/AEBranchAndFinancialInstitutionIdentification5_1"
    },
    "CreditorAccount": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AECashAccount5_0"
      }
    }
  },
  "additionalProperties": false
}

{
  "description": "A unique and immutable identifier produced by the LFI to identify the scheduled payment resource. This identifier has no meaning to the account owner.",
  "type": "string",
  "minLength": 1,
  "maxLength": 40
}

{
  "description": "Specifies the type of scheduled payment date provided under ScheduledPaymentDateTime. \n  Encoded with allowable values of:\n  \"Arrival\" - User1 specifies the date for the arrival of funds in the beneficiary (Creditor) account\n  \"Execution\" - User1 specifies the date which the payment needs to be executed from the User 1 (Debtor) account.\n",
  "type": "string",
  "enum": [
    "Arrival",
    "Execution"
  ]
}

{
  "description": "Date (and time) information related to the scheduled payment (Arrival or Execution) based on the ScheduleType field. All dates in the JSON payloads are represented in ISO 8601 date-time format. \nAll date-time fields in responses must include the timezone. An example is below:\n2017-04-05T10:43:07+00:00",
  "type": "string",
  "format": "date-time"
}

{
  "description": "Unique reference in the context of the creditor, provided by the creditor to the User1 (Debtor), to unambiguously refer to the payment transaction. Usage: If available, the initiating party (i.e. Debtor) provides this reference in the structured remittance information, to enable reconciliation by the Creditor upon receipt of the amount of money. This field is populated by the User 1 (who is the initiating party of the payment e.g. the Debtor). Field is free format text",
  "type": "string",
  "minLength": 1,
  "maxLength": 35
}

{
  "description": "Reference in the context of the User 1 (i.e. the Debtor) to refer to the payment transaction. \nUsage: If available, the initiating party (i.e. Debtor) generates this reference for internal purposes (e.g. to enable reconciliation, refer to a PO, invoice etc). This field is captured by the LFI and is not transmitted via the payment rails to the Creditor of the payment.\n",
  "type": "string",
  "minLength": 1,
  "maxLength": 35
}

{
  "type": "object",
  "required": [
    "Amount",
    "Currency"
  ],
  "description": "The amount of money that was moved between the User 1 (Debtor) and the payment beneficiary (Creditor) by the LFI, before adding any charges from the sending LFI.\nIt is expressed in the currency as ordered by the User 1 (i.e. the initiating party of the payment). This amount is transported unchanged through the transaction chain.\n",
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
    },
    "Currency": {
      "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
    }
  },
  "additionalProperties": false
}

{
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "type": "string",
  "pattern": "^\\d{1,13}$|^\\d{1,13}\\.\\d{1,5}$"
}

{
  "description": "A 3 character alphabetic code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'.",
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "example": "AED"
}

{
  "type": "object",
  "required": [
    "SchemeName",
    "Identification"
  ],
  "description": "Creditor Agent refers to the Financial Institution that manages the account on behalf of the scheduled payment beneficiary party, managing registration, booking of entries on the account, calculating balances on the account and providing information about the account. This is the servicing Financial Institution of the Beneficiary account.\n",
  "properties": {
    "SchemeName": {
      "$ref": "#/components/schemas/AEExternalFinancialInstitutionIdentificationCode"
    },
    "Identification": {
      "$ref": "#/components/schemas/Identification_1"
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "SchemeName",
    "Identification"
  ],
  "description": "Provides the details to identify the beneficiary account.",
  "properties": {
    "SchemeName": {
      "$ref": "#/components/schemas/AEExternalAccountIdentificationCode1"
    },
    "Identification": {
      "$ref": "#/components/schemas/Identification_0"
    }
  },
  "additionalProperties": false
}

{
  "description": "Identification for the account assigned by the LFI based on the Account Scheme Name. This identification is known by the User 1 account owner. For IBAN, refer to the ISO Standard 13616.\n",
  "type": "string",
  "minLength": 1,
  "maxLength": 400
}

